class OrganismoORUM:

    LIMIAR_SCORE = 0.85
    RECORRENCIA_MIN = 3
    AGENTES_MIN = 2

    def __init__(self):

        self.efemera: Dict[str, Vetor] = {}
        self.axiomas: Dict[str, Vetor] = {}
        self.ledger: List[dict] = []

    def fingerprint(self, texto: str) -> str:
        texto = " ".join(texto.strip().lower().split())
        return sha256(texto.encode()).hexdigest()

    def observar(self, texto: str, agente: str):

        h = self.fingerprint(texto)

        agora = utc_now()

        if h not in self.efemera:

            self.efemera[h] = Vetor(
                hash=h,
                primeira_observacao=agora,
                ultima_observacao=agora,
                agentes={agente},
            )

            return {
                "estado": "efemero",
                "hash": h[:8]
            }

        v = self.efemera[h]

        v.recorrencia += 1
        v.ultima_observacao = agora
        v.agentes.add(agente)

        self.avaliar(v)

        return {
            "estado": "observado",
            "score": round(v.score,3),
            "hash": h[:8]
        }

    def avaliar(self, v: Vetor):

        r = min(v.recorrencia / self.RECORRENCIA_MIN, 1.0)

        a = min(len(v.agentes) / self.AGENTES_MIN, 1.0)

        c = 1.0 if v.contradicoes == 0 else 0.0

        v.score = (
            0.45 * r +
            0.35 * a +
            0.20 * c
        )

        if (
            not v.sedimentado
            and v.score >= self.LIMIAR_SCORE
        ):
            self.sedimentar(v)

    def sedimentar(self, v: Vetor):

        v.sedimentado = True

        self.axiomas[v.hash] = v

